#include "bip39.h"

#include <cstring>
#include <sstream>
#include <stdexcept>

#include "sha256.h"
#include "wordlist.h"  // generated by CMake from data/english.txt

namespace bip39 {

void sha256_short(const uint8_t* msg, size_t len, uint8_t out[32]) {
    if (len > 55) throw std::invalid_argument("sha256_short: message longer than 55 bytes");
    uint8_t buf[64] = {0};
    memcpy(buf, msg, len);
    buf[len] = 0x80;
    uint64_t bits = (uint64_t)len * 8;
    for (int i = 0; i < 8; i++) buf[63 - i] = (uint8_t)(bits >> (8 * i));

    uint32_t blk[16], h[8];
    for (int i = 0; i < 16; i++)
        blk[i] = (uint32_t)buf[4 * i] << 24 | (uint32_t)buf[4 * i + 1] << 16 | (uint32_t)buf[4 * i + 2] << 8 | buf[4 * i + 3];
    sha256_block(blk, h);
    for (int i = 0; i < 8; i++)
        for (int j = 0; j < 4; j++) out[4 * i + j] = (uint8_t)(h[i] >> (24 - 8 * j));
}

static bool get_bit(const uint8_t* p, size_t i) { return (p[i / 8] >> (7 - i % 8)) & 1; }

std::vector<uint16_t> entropy_to_indices(const uint8_t* ent, size_t len) {
    if (len != 16 && len != 32) throw std::invalid_argument("entropy must be 16 or 32 bytes");
    uint8_t data[33];
    uint8_t hash[32];
    memcpy(data, ent, len);
    sha256_short(ent, len, hash);
    data[len] = hash[0];  // only the top len/4 bits of it are used

    size_t words = (len * 8 + len / 4) / 11;
    std::vector<uint16_t> idx(words);
    for (size_t w = 0; w < words; w++) {
        uint16_t v = 0;
        for (size_t b = 0; b < 11; b++) v = (uint16_t)(v << 1 | get_bit(data, w * 11 + b));
        idx[w] = v;
    }
    return idx;
}

bool indices_valid(const std::vector<uint16_t>& idx) {
    if (idx.size() != 12 && idx.size() != 24) return false;
    size_t entBytes = idx.size() == 12 ? 16 : 32;
    uint8_t data[33] = {0};
    for (size_t w = 0; w < idx.size(); w++) {
        if (idx[w] >= 2048) return false;
        for (size_t b = 0; b < 11; b++)
            if (idx[w] >> (10 - b) & 1) data[(w * 11 + b) / 8] |= (uint8_t)(0x80 >> ((w * 11 + b) % 8));
    }
    return entropy_to_indices(data, entBytes) == idx;
}

std::string to_words(const std::vector<uint16_t>& idx) {
    std::string s;
    for (size_t i = 0; i < idx.size(); i++) {
        if (i) s += ' ';
        s += BIP39_WORDS[idx[i]];
    }
    return s;
}

bool from_words(const std::string& text, std::vector<uint16_t>& idx) {
    idx.clear();
    std::istringstream in(text);
    std::string w;
    while (in >> w) {
        // The list is sorted: binary search.
        int lo = 0, hi = 2047, found = -1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            int c = w.compare(BIP39_WORDS[mid]);
            if (c == 0) { found = mid; break; }
            if (c < 0) hi = mid - 1; else lo = mid + 1;
        }
        if (found < 0) return false;
        idx.push_back((uint16_t)found);
    }
    return true;
}

}  // namespace bip39
